alter function public.end_business_provider(uuid,text,uuid,text) rename to end_business_provider_before_notice;
revoke all on function public.end_business_provider_before_notice(uuid,text,uuid,text) from public,anon,authenticated,service_role;
create function public.end_business_provider(p_user_id uuid,p_verified_email text,p_business_id uuid,p_reason text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$begin
 if (exists(select 1 from public.provider_change_policy) or exists(select 1 from public.provider_change_requests where business_workspace_id=p_business_id and status in('awaiting_policy','awaiting_notice','notified'))) and exists(select 1 from public.workspace_providers where customer_workspace_id=p_business_id and status='active') then raise exception 'provider_change_completion_required';end if;
 return public.end_business_provider_before_notice(p_user_id,p_verified_email,p_business_id,p_reason);end;$$;
DO $$declare definition text;begin select pg_get_functiondef('public.complete_provider_change_without_payer(uuid,uuid,text)'::regprocedure) into definition;definition:=replace(definition,'public.end_business_provider(','public.end_business_provider_before_notice(');execute definition;end;$$;
revoke all on function public.end_business_provider(uuid,text,uuid,text) from public,anon,authenticated;grant execute on function public.end_business_provider(uuid,text,uuid,text) to service_role;
create function public.read_provider_change_requests(p_workspace_id uuid,p_user_id uuid,p_verified_email text) returns jsonb language plpgsql stable security definer set search_path=public,pg_temp as $$begin
 perform public.connect_assert_reader(p_workspace_id,p_user_id,p_verified_email);
 return coalesce((select jsonb_agg(to_jsonb(q) order by requested_at desc,id) from public.provider_change_requests q left join public.workspace_providers p on p.id=q.old_provider_id where q.business_workspace_id=p_workspace_id or p.provider_workspace_id=p_workspace_id),'[]');end;$$;
revoke all on function public.read_provider_change_requests(uuid,uuid,text) from public,anon,authenticated;grant execute on function public.read_provider_change_requests(uuid,uuid,text) to service_role;
create table public.provider_change_responses(id uuid primary key default gen_random_uuid(),request_id uuid not null references public.provider_change_requests(id),agency_workspace_id uuid not null references public.workspaces(id),responded_by uuid not null references public.users(id),kind text not null check(kind in('acknowledged','handoff_ready','question','objection')),note text not null check(length(note)<=5000),idempotency_key text not null,created_at timestamptz not null default now(),unique(request_id,idempotency_key));
alter table public.provider_change_responses enable row level security;revoke all on public.provider_change_responses from public,anon,authenticated,service_role;
create trigger money_immutable before update or delete on public.provider_change_responses for each row execute function public.money_immutable_guard();
create function public.respond_provider_change(p_request_id uuid,p_user_id uuid,p_verified_email text,p_kind text,p_note text,p_key text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare q public.provider_change_requests%rowtype;p public.workspace_providers%rowtype;r public.provider_change_responses%rowtype;begin
 select * into q from public.provider_change_requests where id=p_request_id for update;select * into p from public.workspace_providers where id=q.old_provider_id;
 perform public.connect_assert_manager(p.provider_workspace_id,p_user_id,p_verified_email);
 if p.status<>'active' or q.status<>'notified' or q.respond_by<now() then raise exception 'provider_response_window_closed';end if;
 if length(p_key) not between 8 and 200 then raise exception 'provider_response_invalid';end if;
 insert into public.provider_change_responses(request_id,agency_workspace_id,responded_by,kind,note,idempotency_key) values(q.id,p.provider_workspace_id,p_user_id,p_kind,p_note,p_key) on conflict do nothing;
 select * into r from public.provider_change_responses where request_id=q.id and idempotency_key=p_key;
 if r.responded_by<>p_user_id or r.kind<>p_kind or r.note<>p_note then raise exception 'provider_response_conflict';end if;return to_jsonb(r);end;$$;
alter function public.acknowledge_provider_change_notice(uuid,uuid,text) rename to acknowledge_provider_change_notice_before_response;
revoke all on function public.acknowledge_provider_change_notice_before_response(uuid,uuid,text) from public,anon,authenticated,service_role;
create function public.acknowledge_provider_change_notice(p_request_id uuid,p_user_id uuid,p_verified_email text) returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare q jsonb;begin
 q:=public.acknowledge_provider_change_notice_before_response(p_request_id,p_user_id,p_verified_email);
 if not exists(select 1 from public.provider_change_responses where request_id=p_request_id and kind='acknowledged') then perform public.respond_provider_change(p_request_id,p_user_id,p_verified_email,'acknowledged','Agency manager acknowledged the notice.','acknowledge:'||p_request_id::text);end if;return q;end;$$;
-- The read includes immutable responses so both parties see the same record.
DO $$declare definition text;begin select pg_get_functiondef('public.read_provider_change_requests(uuid,uuid,text)'::regprocedure) into definition;definition:=replace(definition,'jsonb_agg(to_jsonb(q) order by requested_at desc,id)','jsonb_agg(to_jsonb(q)||jsonb_build_object(''responses'',coalesce((select jsonb_agg(to_jsonb(r) order by r.created_at,r.id) from public.provider_change_responses r where r.request_id=q.id),''[]'')) order by requested_at desc,q.id)');execute definition;end;$$;
revoke all on function public.respond_provider_change(uuid,uuid,text,text,text,text),public.acknowledge_provider_change_notice(uuid,uuid,text) from public,anon,authenticated;grant execute on function public.respond_provider_change(uuid,uuid,text,text,text,text),public.acknowledge_provider_change_notice(uuid,uuid,text) to service_role;
-- A bundled agency invoice uses persisted provider subscription/item ownership,
-- never a line's claimed business metadata. Unpriced client lines stay closed.
create function public.resolve_invoice_business_line(p_payer_workspace uuid,p_subscription text,p_item text,p_basis bigint,p_currency text) returns uuid language plpgsql stable security definer set search_path=public,pg_temp as $$declare business uuid;begin
 if p_item is not null then select coalesce((to_jsonb(i)->>'business_workspace_id')::uuid,l.workspace_id) into business from public.subscription_items i join public.subscriptions s on s.id=i.subscription_id join public.accounts a on a.id=s.account_id left join public.tenants t on t.id=i.tenant_id left join public.tenant_workspace_links l on l.tenant_stable_id=t.stable_id where a.workspace_id=p_payer_workspace and s.stripe_subscription_id=p_subscription and i.stripe_item_id=p_item and i.amount_cents is not null and i.amount_cents>=p_basis and s.currency=p_currency limit 1;
 if business is not null then return business;end if;end if;
 if exists(select 1 from public.workspaces where id=p_payer_workspace and kind='customer') then return p_payer_workspace;end if;return null;end;$$;
revoke all on function public.resolve_invoice_business_line(uuid,text,text,bigint,text) from public,anon,authenticated;grant execute on function public.resolve_invoice_business_line(uuid,text,text,bigint,text) to service_role;
create table public.money_reconciliation_issues(account_id text not null,event_id text not null,event_type text not null,reason text not null,object_id text,created_at timestamptz not null default now(),primary key(account_id,event_id,reason));
alter table public.money_reconciliation_issues enable row level security;revoke all on public.money_reconciliation_issues from public,anon,authenticated,service_role;
create trigger money_immutable before update or delete on public.money_reconciliation_issues for each row execute function public.money_immutable_guard();
create function public.record_money_reconciliation_issue(p_account text,p_event text,p_type text,p_reason text,p_object text) returns void language plpgsql security definer set search_path=public,pg_temp as $$begin
 insert into public.money_reconciliation_issues(account_id,event_id,event_type,reason,object_id) values(p_account,p_event,p_type,p_reason,p_object) on conflict do nothing;
 if not exists(select 1 from public.money_reconciliation_issues where account_id=p_account and event_id=p_event and event_type=p_type and reason=p_reason and object_id is not distinct from p_object) then raise exception 'money_reconciliation_identity_conflict';end if;end;$$;
revoke all on function public.record_money_reconciliation_issue(text,text,text,text,text) from public,anon,authenticated;grant execute on function public.record_money_reconciliation_issue(text,text,text,text,text) to service_role;
